import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"GUI Templates","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/station/gui.md","filePath":"en/modules/station/gui.md","lastUpdated":0}`),a={name:`en/modules/station/gui.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="gui-templates" tabindex="-1">GUI Templates <a class="header-anchor" href="#gui-templates" aria-label="Permalink to “GUI Templates”">​</a></h1><p>EmakiStation has four window templates under <code>plugins/EmakiStation/gui/</code>.</p><table tabindex="0"><thead><tr><th>Template</th><th>Window</th><th>Station configuration key</th></tr></thead><tbody><tr><td><code>station_catalog.yml</code></td><td>Recipe catalog (page 1)</td><td><code>layout</code></td></tr><tr><td><code>station_preview.yml</code></td><td>Material preview (page 2)</td><td><code>preview_layout</code></td></tr><tr><td><code>station_queue.yml</code></td><td>Craft queue (page 3)</td><td><code>queue_layout</code></td></tr><tr><td><code>station_dismantle.yml</code></td><td>Dismantle window</td><td><code>layout</code> of a dismantle station</td></tr></tbody></table><p>The first three form the three-page crafting flow: the catalog submits on left click and opens the material preview on right click; the preview confirms the submission; the queue page views, cancels, claims and buys queue slots. The dismantle window is separate and entered through <code>/emakistation dismantle &lt;station&gt;</code>.</p><h2 id="slots-must-declare-type-explicitly" tabindex="-1">Slots Must Declare <code>type</code> Explicitly <a class="header-anchor" href="#slots-must-declare-type-explicitly" aria-label="Permalink to “Slots Must Declare type Explicitly”">​</a></h2><p>EmakiStation slots <strong>must declare <code>type</code> explicitly</strong>. The CoreLib template parser only infers types for a few Forge-specific key names; a custom key name without <code>type</code> is nothing but decoration.</p><p>Resolution is &quot;use <code>type</code> first, fall back to the slot key name&quot;, so <code>type</code> can only be omitted when the key name happens to equal the type name.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  recipe_list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;recipe_list&quot;</span></span></code></pre></div><h2 id="recipe-catalog-types" tabindex="-1">Recipe Catalog Types <a class="header-anchor" href="#recipe-catalog-types" aria-label="Permalink to “Recipe Catalog Types”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>Purpose</th></tr></thead><tbody><tr><td><code>recipe_list</code></td><td>List recipes. <strong>Required</strong>, or layout validation fails.</td></tr><tr><td><code>queue_open</code></td><td>Open the craft queue page.</td></tr><tr><td><code>batch_multiplier</code></td><td>Cycle the multiplier; left click increases, right click decreases.</td></tr><tr><td><code>output_toggle</code></td><td>Switch output routing.</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>Pagination.</td></tr><tr><td><code>close</code></td><td>Close the window.</td></tr></tbody></table><p>This page has <strong>no</strong> input slot. Players do not place materials into the window; materials are deducted from the merged inventory-plus-warehouse pool at submission time.</p><p>Catalog click behaviour: left-clicking an entry submits it at the current multiplier; right-clicking opens the material preview; an entry that is not unlocked (<code>display_condition</code> unsatisfied) does nothing on click.</p><h2 id="material-preview-types" tabindex="-1">Material Preview Types <a class="header-anchor" href="#material-preview-types" aria-label="Permalink to “Material Preview Types”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>Purpose</th></tr></thead><tbody><tr><td><code>material_list</code></td><td>List the selected recipe&#39;s material requirements. <strong>Required</strong>.</td></tr><tr><td><code>recipe_display</code></td><td>Show the recipe being previewed.</td></tr><tr><td><code>cost_display</code></td><td>Show the currency cost and the player&#39;s balance.</td></tr><tr><td><code>max_craftable</code></td><td>Show how many crafts the materials and balance allow, and jump straight to the maximum on click.</td></tr><tr><td><code>batch_multiplier</code></td><td>Cycle the multiplier.</td></tr><tr><td><code>confirm</code></td><td>Submit.</td></tr><tr><td><code>back</code></td><td>Return to the catalog, landing on the original page.</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>Material list pagination.</td></tr><tr><td><code>close</code></td><td>Close the window.</td></tr></tbody></table><p>This page is read-only and does not accept inserted items.</p><p>The multiplier button cycles through the fixed steps <code>1 → 10 → 64 → 1000</code> (left click forward, right click backward, wrapping around). <code>max_craftable</code> computes the ceiling from materials and balance and <strong>sets it as the current multiplier</strong>.</p><h3 id="material-amount-display-rules" tabindex="-1">Material Amount Display Rules <a class="header-anchor" href="#material-amount-display-rules" aria-label="Permalink to “Material Amount Display Rules”">​</a></h3><table tabindex="0"><thead><tr><th>Requirement</th><th>Display</th></tr></thead><tbody><tr><td>≤ 99</td><td>The icon carries the real number, drawn directly by the client.</td></tr><tr><td>≥ 100</td><td>The icon amount is fixed at 1 with no number drawn; the real amount appears only in the lore&#39;s <code>%required_exact%</code>.</td></tr></tbody></table><p>Always keep <code>%required_exact%</code> in the lore, or players will have no way to learn large requirements.</p><p>Amounts of 65–99 exceed the natural stack size of most items, so the plugin temporarily raises the <code>max_stack_size</code> component of the rendered icon. That change applies only to the display icon inside the window and is never handed to the player.</p><h2 id="craft-queue-types" tabindex="-1">Craft Queue Types <a class="header-anchor" href="#craft-queue-types" aria-label="Permalink to “Craft Queue Types”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>Purpose</th></tr></thead><tbody><tr><td><code>queue_view</code></td><td>List queue entries. <strong>Required</strong>.</td></tr><tr><td><code>capacity_display</code></td><td>Show used / ceiling along with where the ceiling comes from.</td></tr><tr><td><code>queue_purchase</code></td><td>Buy extra queue slots; left click buys one, Shift buys a whole batch.</td></tr><tr><td><code>claim_all</code></td><td>Claim every pending output.</td></tr><tr><td><code>back</code></td><td>Return to the catalog, landing on the original page.</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>Queue pagination.</td></tr><tr><td><code>close</code></td><td>Close the window.</td></tr></tbody></table><p>This page is read-only and does not accept inserted items.</p><p>Queue entry click behaviour: clicking a <code>PENDING_CLAIM</code> entry is equivalent to &quot;claim all&quot;; clicking any other entry cancels it. The <code>queue_purchase</code> &quot;whole batch&quot; click uses the largest batch option (see <a href="./queue-costs.html">Paid Queue Slots</a>).</p><h2 id="dismantle-window-types" tabindex="-1">Dismantle Window Types <a class="header-anchor" href="#dismantle-window-types" aria-label="Permalink to “Dismantle Window Types”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>Purpose</th></tr></thead><tbody><tr><td><code>dismantle_input</code></td><td>Show the selected recipe&#39;s input item icon (a read-only preview; no item is placed).</td></tr><tr><td><code>dismantle_item_display</code></td><td>Alias of <code>dismantle_input</code>.</td></tr><tr><td><code>dismantle_rolls_display</code></td><td>Show the roll count range (<code>%rolls_min%</code> / <code>%rolls_max%</code>).</td></tr><tr><td><code>dismantle_output_list</code></td><td>Output list across several paginated cells, using the <code>pool_entry</code> / <code>rolled_output</code> virtual items.</td></tr><tr><td><code>dismantle_confirm</code></td><td>Confirm the dismantle, or claim already-rolled outputs.</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>Output list pagination.</td></tr><tr><td><code>back</code></td><td>Return to the catalog.</td></tr><tr><td><code>close</code></td><td>Close the window.</td></tr></tbody></table><p>The pagination controls serve both the probability-pool preview and the rolled-output list; the page ceiling switches with the current state.</p><h2 id="complete-placeholder-reference" tabindex="-1">Complete Placeholder Reference <a class="header-anchor" href="#complete-placeholder-reference" aria-label="Permalink to “Complete Placeholder Reference”">​</a></h2><p>The <code>%...%</code> tokens inside window templates are <strong>internal template placeholders</strong> rendered by EmakiStation itself, unrelated to PlaceholderAPI (PAPI variables are only resolved inside condition-expression text).</p><h3 id="title-placeholders-top-level-template-title" tabindex="-1">Title Placeholders (top-level template <code>title</code>) <a class="header-anchor" href="#title-placeholders-top-level-template-title" aria-label="Permalink to “Title Placeholders (top-level template title)”">​</a></h3><table tabindex="0"><thead><tr><th>Placeholder</th><th>Recipe catalog</th><th>Material preview</th><th>Craft queue</th><th>Dismantle window</th></tr></thead><tbody><tr><td><code>%station_name%</code></td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>%station%</code></td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>%player%</code></td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>%recipe%</code></td><td>—</td><td>✓</td><td>—</td><td>✓</td></tr><tr><td><code>%recipe_name%</code></td><td>—</td><td>✓</td><td>—</td><td>✓</td></tr><tr><td><code>%page%</code></td><td>✓</td><td>—</td><td>—</td><td>—</td></tr><tr><td><code>%pages%</code></td><td>✓</td><td>—</td><td>—</td><td>—</td></tr><tr><td><code>%used%</code> / <code>%max%</code></td><td>—</td><td>—</td><td>✓</td><td>—</td></tr></tbody></table><p>On the catalog title, <code>%pages%</code> resolves to the <strong>total number of recipe entries</strong> (as implemented), not the page count; use the <code>page_info</code> slot for the real page count.</p><h3 id="catalog-slot-placeholders" tabindex="-1">Catalog Slot Placeholders <a class="header-anchor" href="#catalog-slot-placeholders" aria-label="Permalink to “Catalog Slot Placeholders”">​</a></h3><table tabindex="0"><thead><tr><th>Slot type</th><th>Available placeholders</th></tr></thead><tbody><tr><td><code>recipe_list</code></td><td><code>%recipe%</code>, <code>%recipe_name%</code>, <code>%result_name%</code>, <code>%result_amount%</code>, <code>%duration%</code>, <code>%batch%</code>, <code>%index%</code>, <code>%page%</code>, <code>%pages%</code>, <code>%conditions%</code>, <code>%costs%</code>, <code>%materials%</code>; locked entries additionally have <code>%lock_reason%</code></td></tr><tr><td><code>batch_multiplier</code></td><td><code>%batch%</code>, <code>%batch_exact%</code></td></tr><tr><td><code>output_toggle</code></td><td><code>%output%</code>, <code>%output_state%</code></td></tr><tr><td><code>page_info</code> / <code>prev_page</code> / <code>next_page</code></td><td><code>%page%</code>, <code>%pages%</code>, <code>%total%</code></td></tr></tbody></table><p><code>%conditions%</code> / <code>%costs%</code> / <code>%materials%</code> are whole-line expansion placeholders: in lore they must occupy a line of their own, and CoreLib expands that line into as many lines as there are entries. Writing <code>Materials: %materials%</code> does not expand.</p><h3 id="preview-slot-placeholders" tabindex="-1">Preview Slot Placeholders <a class="header-anchor" href="#preview-slot-placeholders" aria-label="Permalink to “Preview Slot Placeholders”">​</a></h3><table tabindex="0"><thead><tr><th>Slot type</th><th>Available placeholders</th></tr></thead><tbody><tr><td><code>material_list</code></td><td><code>%material%</code>, <code>%material_id%</code>, <code>%requirement_id%</code>, <code>%count_key%</code>, <code>%required%</code>, <code>%required_exact%</code>, <code>%owned%</code>, <code>%owned_exact%</code>, <code>%satisfied%</code>, <code>%consumed%</code>, <code>%alternatives%</code>, <code>%index%</code>, <code>%page%</code>, <code>%pages%</code></td></tr><tr><td><code>recipe_display</code></td><td><code>%recipe%</code>, <code>%recipe_name%</code>, <code>%result_name%</code>, <code>%result_amount%</code>, <code>%duration%</code>, <code>%batch%</code></td></tr><tr><td><code>cost_display</code></td><td><code>%cost%</code>, <code>%cost_exact%</code>, <code>%currency%</code>, <code>%balance%</code>, <code>%affordable%</code>, <code>%free%</code></td></tr><tr><td><code>max_craftable</code></td><td><code>%max%</code>, <code>%max_exact%</code>, <code>%batch%</code></td></tr><tr><td><code>batch_multiplier</code></td><td><code>%batch%</code>, <code>%batch_exact%</code></td></tr><tr><td><code>confirm</code></td><td><code>%recipe%</code>, <code>%recipe_name%</code>, <code>%batch%</code>; when blocked (switching to the <code>confirm_blocked</code> virtual item): <code>%block_reason%</code>, <code>%block_text%</code></td></tr><tr><td><code>page_info</code> / <code>prev_page</code> / <code>next_page</code></td><td><code>%page%</code>, <code>%pages%</code>, <code>%total%</code></td></tr></tbody></table><h3 id="queue-slot-placeholders" tabindex="-1">Queue Slot Placeholders <a class="header-anchor" href="#queue-slot-placeholders" aria-label="Permalink to “Queue Slot Placeholders”">​</a></h3><table tabindex="0"><thead><tr><th>Slot type</th><th>Available placeholders</th></tr></thead><tbody><tr><td><code>queue_view</code></td><td>Normal entries: <code>%index%</code>, <code>%recipe%</code>, <code>%batch%</code>, <code>%state%</code>, <code>%remaining%</code>, <code>%cost%</code>, <code>%currency%</code>, <code>%page%</code>, <code>%pages%</code> (pending entries switch to the <code>queue_pending</code> virtual item with the same placeholder set)</td></tr><tr><td><code>capacity_display</code></td><td><code>%used%</code>, <code>%max%</code>, <code>%purchased%</code>, <code>%base%</code>, <code>%ceiling%</code>, <code>%pending%</code></td></tr><tr><td><code>queue_purchase</code></td><td>When purchasable: <code>%slots%</code>, <code>%cost%</code>, <code>%currency%</code>, <code>%items%</code>; when not (switching to the <code>purchase_unavailable</code> virtual item): <code>%reason%</code>, <code>%reason_text%</code></td></tr><tr><td><code>claim_all</code></td><td><code>%pending%</code></td></tr><tr><td><code>page_info</code> / <code>prev_page</code> / <code>next_page</code></td><td><code>%page%</code>, <code>%pages%</code>, <code>%total%</code></td></tr></tbody></table><h3 id="dismantle-slot-placeholders" tabindex="-1">Dismantle Slot Placeholders <a class="header-anchor" href="#dismantle-slot-placeholders" aria-label="Permalink to “Dismantle Slot Placeholders”">​</a></h3><table tabindex="0"><thead><tr><th>Slot type</th><th>Available placeholders</th></tr></thead><tbody><tr><td><code>dismantle_input</code> / <code>dismantle_item_display</code></td><td><code>%recipe%</code>, <code>%recipe_name%</code>, <code>%input%</code> (switches to the <code>no_recipe</code> virtual item when nothing matches)</td></tr><tr><td><code>dismantle_rolls_display</code></td><td><code>%rolls_min%</code>, <code>%rolls_max%</code>, <code>%recipe_name%</code></td></tr><tr><td><code>dismantle_output_list</code></td><td>Pool entries: <code>%item%</code>, <code>%amount_min%</code>, <code>%amount_max%</code>, <code>%weight%</code>, <code>%chance%</code>, <code>%index%</code>, <code>%page%</code>, <code>%pages%</code>; rolled outputs: <code>%item%</code>, <code>%amount%</code>, <code>%amount_exact%</code>, <code>%index%</code>, <code>%total%</code></td></tr><tr><td><code>dismantle_confirm</code></td><td>Before rolling: <code>%recipe%</code>, <code>%recipe_name%</code>; after rolling (switching to the <code>dismantle_claim</code> virtual item): <code>%recipe_name%</code>, <code>%output_count%</code></td></tr><tr><td><code>page_info</code> / <code>prev_page</code> / <code>next_page</code></td><td><code>%page%</code>, <code>%pages%</code>, <code>%total%</code></td></tr></tbody></table><p><code>%chance%</code> is the weight-derived percentage (one decimal place) and <code>%weight%</code> is the raw weight.</p><h2 id="virtual-items-and-texts" tabindex="-1"><code>virtual_items</code> and <code>texts</code> <a class="header-anchor" href="#virtual-items-and-texts" aria-label="Permalink to “virtual_items and texts”">​</a></h2><p>All four templates have a <code>virtual_items</code> section defining the icon forms of list entries:</p><table tabindex="0"><thead><tr><th>Template</th><th><code>virtual_items</code> keys in use</th></tr></thead><tbody><tr><td><code>station_catalog.yml</code></td><td><code>recipe_entry</code>, <code>recipe_locked</code></td></tr><tr><td><code>station_preview.yml</code></td><td><code>material_satisfied</code>, <code>material_missing</code>, <code>confirm_blocked</code></td></tr><tr><td><code>station_queue.yml</code></td><td><code>queue_entry</code>, <code>queue_pending</code>, <code>purchase_unavailable</code></td></tr><tr><td><code>station_dismantle.yml</code></td><td><code>no_recipe</code>, <code>dismantle_input</code>, <code>pool_entry</code>, <code>rolled_output</code>, <code>dismantle_claim</code></td></tr></tbody></table><p>When a key is missing the renderer falls back to a built-in icon and text (for example a grey dye for a locked catalog entry, or a barrier for a blocked confirm). The three crafting templates also have a <code>texts</code> section for configurable line fragments: <code>texts.recipe.*</code> and <code>texts.output_state.*</code> on the catalog, <code>texts.block_reason.*</code> and <code>texts.output_state.*</code> on the preview, and <code>texts.purchase_reason.*</code> on the queue page. The dismantle window has no <code>texts</code> section.</p><p><code>texts.block_reason.*</code> and <code>texts.purchase_reason.*</code> keys correspond to the plugin&#39;s internal rejection reason keys (such as <code>insufficient_materials</code>, <code>station.queue_full</code>, <code>no_price_defined</code>); a missing key shows the raw reason key instead.</p><h2 id="interaction-constraints" tabindex="-1">Interaction Constraints <a class="header-anchor" href="#interaction-constraints" aria-label="Permalink to “Interaction Constraints”">​</a></h2><ul><li>Every click on a top-inventory slot is cancelled (icons cannot be taken), and dragging into the top inventory is blocked.</li><li>Number-key, offhand-swap and unsupported combination clicks are ignored.</li><li>Rapid clicking in one session is throttled by <code>gui.click_throttle_ms</code>.</li><li>Open windows repaint on the <code>gui.refresh_interval_ticks</code> interval, and never repaint off the player&#39;s owner thread.</li></ul>`,49)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};